#nullable enable // autogenerated

using MVZ2Logic.Conditions;
using MVZ2Logic.Resources;
using PVZEngine;

namespace MVZ2Logic.Curses
{
    [PropertyRegistryRegion(LogicPropertyRegions.curse)]
    public static class LogicCurseProps
    {
        public static PropertyMeta<T> Get<T>(string name)
        {
            return new PropertyMeta<T>(name);
        }
        public static readonly PropertyMeta<SpriteReference> SPRITE_REFERENCE = Get<SpriteReference>("sprite_reference");
        public static SpriteReference? GetSpriteReference(this CurseDefinition definition)
        {
            return definition.GetProperty<SpriteReference>(SPRITE_REFERENCE);
        }
        public static void SetSpriteReference(this CurseDefinition definition, SpriteReference? spriteReference)
        {
            definition.SetProperty(SPRITE_REFERENCE, spriteReference);
        }

        public static readonly PropertyMeta<NamespaceID> BUFF_ID = Get<NamespaceID>("buff_id");
        public static void SetBuffID(this CurseDefinition curse, NamespaceID? id)
        {
            curse.SetProperty(BUFF_ID, id);
        }
        public static NamespaceID? GetBuffID(this CurseDefinition curse)
        {
            return curse.GetProperty<NamespaceID>(BUFF_ID);
        }

        #region 制品名称
        public static readonly PropertyMeta<string> NAME = Get<string>("name");
        public static string? GetCurseName(this CurseDefinition definition)
        {
            return definition.GetProperty<string>(NAME);
        }
        public static void SetCurseName(this CurseDefinition definition, string value)
        {
            definition.SetProperty(NAME, value);
        }
        #endregion

        #region 制品工具提示
        public static readonly PropertyMeta<string> TOOLTIP = Get<string>("tooltip");
        public static string? GetCurseTooltip(this CurseDefinition definition)
        {
            return definition.GetProperty<string>(TOOLTIP);
        }
        public static void SetCurseTooltip(this CurseDefinition definition, string value)
        {
            definition.SetProperty(TOOLTIP, value);
        }
        #endregion

        #region 制品解锁
        public static readonly PropertyMeta<IConditionList> UNLOCK = Get<IConditionList>("unlock");
        public static IConditionList? GetUnlockConditions(this CurseDefinition definition)
        {
            return definition.GetProperty<IConditionList>(UNLOCK);
        }
        public static void SetUnlockConditions(this CurseDefinition definition, IConditionList? value)
        {
            definition.SetProperty(UNLOCK, value);
        }
        #endregion
    }
}

